Local Ltac bck := let K := fresh "KC" in
  if_cases K; zify_cond K;
  [exfalso; rewrite ?land1x, ?zb_lxor_ones in K by lia; Z.div_mod_to_equations; lia | clear K].
Local Ltac bprem := first [eassumption | solve [try unfold zlen in *; rewrite ?length_skipn; repeat split; first [assumption | lia]]].
Local Ltac regeq := unfold mkR; repeat (lazymatch goal with |- TNode _ _ _ = TNode _ _ _ => f_equal | |- Some _ = Some _ => f_equal
  | |- TEmpty = TEmpty => reflexivity | |- None = None => reflexivity end); try reflexivity; try (apply f_equal; lia).

Lemma fse_build_proof : fse_build_stmt.
Proof.
  unfold fse_build_stmt, PFSE_BUILD_DT.
  intros ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m DT NC WK wks msv tl nc jdt jw d lo
    BD MSV0 WKS JDT LJDT JW LJW NCB NCR DT0 DTA WK0 WKA NC0 NCA DW DN WN STK LOS DL WL NL MI -> -> -> -> -> ->.
  pose proof (build_dtable_inv nc msv tl wks d BD) as BI. try specialize (BI MSV0).
  destruct BI as (TLR & MSVR & WKSZ & syms1 & snext & hT & fm & syms2 & position & cells & LP & BR & BL & ->).
  unfold FSE_DTABLE_SIZE, FSE_BUILD_DTABLE_WKSP_SIZE, FSE_BUILD_STACK in *.
  pose proof JDT as BDT. apply u8arr_bound in BDT. pose proof JW as BWK. apply u8arr_bound in BWK.
  pose proof NCB as BNC. apply bytes_at_bound in BNC. rewrite u16s_length, length_map in BNC.
  pose proof (bv_unsigned_in_range 64 sp) as RSP. unfold bv_modulus in RSP. cbn in RSP.
  pose proof (lowprob_len _ _ _ _ _ _ _ _ _ LP ltac:(lia) ltac:(lia)) as HNCL. rewrite Z2Nat.id in HNCL by lia.
  assert (ESP : sp = Z_to_bv 64 (bv_unsigned sp)) by (symmetry; apply Z_to_bv_bv_unsigned).
  set (SPV := bv_unsigned sp) in *. rewrite ESP. clear ESP. clearbody SPV.
  assert (P2 : 2 <= 2^tl <= 4096).
  { assert (Q1 : 2^1 <= 2^tl) by (apply Z.pow_le_mono_r; lia). assert (Q2 : 2^tl <= 2^12) by (apply Z.pow_le_mono_r; lia).
    change (2^1) with 2 in Q1. change (2^12) with 4096 in Q2. lia. }
  pose proof (munch_refl [(SPV - 128, SPV); (DT, DT + (1 + 2^tl) * 4); (WK, WK + (2 * (msv + 1) + 2^tl + 8))] m) as MU0.
  pose proof (wmono_refl usegs m) as WM0.
  zstep. carve_frame 128%nat STK.
  do 15 zstep.
  zstep. zstep. zstep. bck.
  zstep. zstep. try (rewrite (shl32_shr31 msv) by lia).
  zstep. try (replace (2 * msv + WK) with (WK + 2 * msv) by lia).
  zstep.
  zstep. bck.
  zstep. zstep. zstep. zstep.
  try (replace (0 <? WK) with true by (symmetry; apply Z.ltb_lt; lia)).
  try (replace (WK + 2 * msv <? 1) with false by (symmetry; apply Z.ltb_ge; lia)).
  try (change (Z.lxor (Z.b2z true) (Z.b2z false)) with 1).
  zstep. try bck.
  zstep. bck.
  zstep. try (rewrite (Z.mod_small msv) by lia).
  zstep. zstep.
  try (replace (WK + msv ≪ 1) with (WK + 2 * msv) by (rewrite Z.shiftl_mul_pow2 by lia; lia)).
  zstep. zstep. bck.
  zstep. zstep. zstep. bck.
  zstep. zstep. zstep. bck.
  zstep. try (rewrite (swrap32_small (msv + 1)) by lia).
  zstep. zstep. zstep. try (rewrite (shl32_shr31 (msv + 1)) by lia).
  zstep. try (replace (1 ≪ (tl mod 64)) with (2^tl) by (rewrite Z.mod_small by lia; rewrite Z.shiftl_mul_pow2 by lia; lia)).
  zstep. zstep.
  zstep.
  bck.
  zstep. zstep. if_cases K3; zify_cond K3; [clear K3 | exfalso; lia].
  zstep. try (rewrite (swrap32_small (tl + -1)) by lia).
  zstep. zstep. bck.
  zstep. if_cases K4; zify_cond K4; [|clear K4].
  { exfalso. clear - K4 NC0 BNC. Z.div_mod_to_equations. lia. }
  zstep. zstep. zstep.
  zstep. zstep. zstep.
  zstep. try (rewrite (sllw_pow2 tl) by lia).
  zstep. try (rewrite (Z.mod_small (msv + 1)) by lia).
  zstep. zstep. zstep.
  zstep. try (rewrite land1x, WKA).
  zstep. try (rewrite land1x, NCA).
  zstep. zstep.
  zstep. try (rewrite (swrap32_small (2^tl + -1)) by lia).
  zstep. try (rewrite (sllw_pow2 (tl + -1)) by lia). try (replace (tl + -1) with (tl - 1) by lia).
  zstep.
  lazymatch goal with H : u8arr _ _ DT jdt |- _ =>
    rewrite <- (firstn_skipn 4 jdt) in H; apply u8arr_app in H; destruct H as [JH JT] end.
  replace (DT + Z.of_nat (length (firstn 4 jdt))) with (DT + 4) in JT by (rewrite firstn_length_le; lia).
  assert (RC : forall s P R R' F0 pc fc0 rv mm ro, R = R' -> evt s P (MS R' F0 pc fc0 rv mm ro) -> evt s P (MS R F0 pc fc0 rv mm ro))
    by (intros; subst; assumption).
  eapply RC; cycle 1.
  eapply (lp_loop _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ NC WK (DT + 4) nc tl (msv + 1) (skipn 4 jdt) jw _
           _ _ _ _ _ _ _ _ _ _ _ _ _
           (Z.to_nat (msv + 1)) 0 (repeat None (Z.to_nat (2^tl))) [] (2^tl - 1) 1).
  all: try (first [exact LP | lia | assumption]).
  all: try lazymatch goal with |- TNode _ _ _ = _ =>
    unfold mkR; repeat (lazymatch goal with |- TNode _ _ _ = TNode _ _ _ => f_equal | |- Some _ = Some _ => f_equal | |- TEmpty = TEmpty => reflexivity | |- None = None => reflexivity end) end.
  all: try reflexivity.
  all: try (rewrite (swrap32_small (2^tl - 1)) by lia).
  all: try (apply f_equal; lia).
  all: try lazymatch goal with |- lp_ok _ _ _ _ _ => unfold lp_ok; rewrite repeat_length; repeat split; try constructor; lia end.
  all: try lazymatch goal with |- lp_inv _ _ _ _ _ _ _ _ _ _ _ => unfold lp_inv; rewrite tsym_none;
    split; [exact JT | split; [exact JW | split; [exact NCB | split; [apply munch_refl | split; [apply wmono_refl | exact MI]]]]] end.
  all: lazymatch goal with |- forall _, _ => idtac end.
  intros m2 syms' snext' hT' fm' y7 y18 y24 ER LSN OK2 INV2.
  injection ER as <- <- <- <-.
  destruct INV2 as (TA2 & WA2 & NB2 & MU2 & WM2 & MI2). unfold lp_W in MU2.
  pose proof (rw_cells_transport usegs _ _ _ _ _ FR MU2 WM2) as FR2.
  lazymatch type of FR2 with ?A -> _ => assert (DFR : A) end.
  { cbn [disjoint_from]. lazymatch goal with |- context [Z.of_nat ?n] => let v := eval vm_compute in (Z.of_nat n) in change (Z.of_nat n) with v end.
    split; [lia | split; [lia | exact I]]. }
  specialize (FR2 DFR). clear FR DFR. rename FR2 into FR.
  pose proof (stk_transport_disjoint usegs _ _ _ _ _ STK MU2 WM2 ltac:(cbn [disjoint_from]; split; [lia | split; [lia | exact I]])) as STK2.
  clear STK. rename STK2 into STK.
  pose proof (u8arr_transport usegs _ _ _ _ _ JH MU2 WM2 ltac:(cbn [disjoint_from]; rewrite firstn_length_le by lia; split; [lia | split; [lia | exact I]])) as JH2.
  clear JH. rename JH2 into JH.
  zstep. zstep. zstep. if_cases KC; zify_cond KC; [| clear KC].
  { exfalso. rewrite ?land1x, ?zb_lxor_ones in KC by lia.
    try (change 3 with (Z.ones 2) in KC; rewrite Z.land_ones in KC by lia). Z.div_mod_to_equations. lia. }
  clear NCB JW JT MI.
  assert (MU3 : munch [(SPV - 128, SPV); (DT, DT + (1 + 2^tl) * 4); (WK, WK + (2 * (msv + 1) + 2^tl + 8))] m m2).
  { eapply munch_trans; [exact MU0 | eapply munch_weaken; [| exact MU2]].
    unfold sub_fp. intros x Hx. cbn [outside] in *. intuition lia. }
  pose proof (wmono_trans usegs _ _ _ WM0 WM2) as WM3.
  clear MU0 MU2 WM0 WM2. rename MU3 into MU0. rename WM3 into WM0.
  zstep. zstep. zstep. zstep.
  assert (LJH : length (firstn 4 jdt) = 4%nat) by (rewrite firstn_length_le; lia).
  pose proof (u8arr_store_ok_n usegs _ DT _ 0 4 (wa (DT + 0)) JH ltac:(lia) ltac:(rewrite LJH; lia) eq_refl) as SOKH.
  rewrite Z.add_0_r in SOKH.
  zstep.
  pose proof OK2 as (_ & _ & _ & _ & FMR).
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ _ ?bb) _) =>
    assert (HW : bb = le2 (Z_to_bv 64 tl) ++ le2 (Z_to_bv 64 fm));
    [ clear - FMR TLR;
      assert (C : (fm = 0 \/ fm = 1) /\ (tl = 1 \/ tl = 2 \/ tl = 3 \/ tl = 4 \/ tl = 5 \/ tl = 6 \/ tl = 7 \/ tl = 8 \/ tl = 9 \/ tl = 10 \/ tl = 11 \/ tl = 12)) by lia;
      destruct C as ([E|E] & C2); subst fm;
      repeat (destruct C2 as [E2|C2]; [subst tl; unfold le4, le2; cbn [Z_to_le_bytes app]; repeat (f_equal; try (apply bv_eq; vm_compute; reflexivity)) |]);
      subst tl; unfold le4, le2; cbn [Z_to_le_bytes app]; repeat (f_equal; try (apply bv_eq; vm_compute; reflexivity))
    | rewrite HW; clear HW ] end.
  pose proof (u8arr_write_bytes usegs _ DT _ 0 (le2 (Z_to_bv 64 tl) ++ le2 (Z_to_bv 64 fm)) JH ltac:(lia) ltac:(rewrite LJH, length_app, !length_le2; lia)) as JH3.
  pose proof (upd_bytes_mid [] (firstn 4 jdt) [] (le2 (Z_to_bv 64 tl) ++ le2 (Z_to_bv 64 fm)) ltac:(rewrite LJH, length_app, !length_le2; reflexivity)) as EUP.
  cbn [length app] in EUP. rewrite !app_nil_r in EUP. change (Z.to_nat 0) with 0%nat in JH3. rewrite EUP, Z.add_0_r in JH3. clear EUP.
  apply (u8arr_frame usegs _ (DT + 4) _ DT (le2 (Z_to_bv 64 tl) ++ le2 (Z_to_bv 64 fm))) in TA2;
    [ | lia | rewrite length_app, !length_le2; lia | rewrite length_app, !length_le2; lia ].
  assert (LSN' : Z.of_nat (length snext) = msv + 1) by exact LSN.
  assert (LJW' : Z.of_nat (length jw) = 2 * (msv + 1) + 2^tl + 8) by first [exact LJW | unfold zlen in LJW; lia | lia].
  assert (DWK : WK + Z.of_nat (length (u16s (map (Z_to_bv 64) snext) ++ skipn (2 * length snext) jw)) <= DT
                \/ DT + Z.of_nat (length (le2 (Z_to_bv 64 tl) ++ le2 (Z_to_bv 64 fm))) <= WK)
    by (rewrite !length_app, !length_le2, u16s_length, length_map, length_skipn; lia).
  apply (u8arr_frame usegs _ WK _ DT (le2 (Z_to_bv 64 tl) ++ le2 (Z_to_bv 64 fm))) in WA2;
    [ | lia | rewrite length_app, !length_le2; lia | exact DWK ].
  clear DWK.
  clear JH. store_done.
  pose proof OK2 as (LS2 & FS2 & HT0 & HT1 & _).
  assert (USP : bv_unsigned (Z_to_bv 64 SPV) = SPV) by (apply inr64_unsigned_lit; unfold inr64; lia).
  assert (HJT' : length (skipn 4 jdt) = (4 * Z.to_nat (2^tl))%nat).
  { rewrite length_skipn. apply Nat2Z.inj. rewrite Nat2Z.inj_sub by lia. rewrite Nat2Z.inj_mul, Z2Nat.id by lia. lia. }
  assert (HJW' : length (skipn (2 * length snext) jw) = Z.to_nat (2^tl + 8)).
  { rewrite length_skipn. apply Nat2Z.inj. rewrite Nat2Z.inj_sub by lia. rewrite Nat2Z.inj_mul, Z2Nat.id by lia. lia. }
  assert (HNC' : 0 < NC /\ NC mod 2 = 0 /\ NC + 2 * Z.of_nat (length nc) <= 2^64)
    by (split; [exact NC0 | split; [exact NCA | lia]]).
  zstep. zstep. if_cases KH; zify_cond KH.
  - destruct BR as [(EH & _) | (NH & GL & EP)].
    { exfalso. subst hT. rewrite (swrap32_small (2^tl - 1)) in KH by lia. Z.div_mod_to_equations. lia. }
    eapply bdt_evt_R.
    { eapply (bdt_gpath ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m SPV DT NC WK msv tl fm hT lo nc (skipn 4 jdt) syms1 snext)
        with (jw' := skipn (2 * length snext) jw).
      all: try bprem.
      lazymatch goal with |- forall _, _ => idtac end.
      intros mq q1 q5 q6 q7 q8 q9 q10 q11 q12 q13 q18 q19 q20 q21 q22 q23 q24 q25 q26 q27 q28 q29 q30 q31 QLS QU1 QU2 QU3 QRW QSK QMU QWM QMI.
      eapply bdt_evt_R;
      [ eapply (bdt_tail ra (Z_to_bv 64 SPV) gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m DT WK msv tl fm lo) with (jt := skipn 4 jdt);
        rewrite ?USP; try unfold FSE_DTABLE_SIZE, FSE_BUILD_DTABLE_WKSP_SIZE, FSE_BUILD_STACK; bprem
      | rewrite ?USP; regeq ]. }
    regeq.
  - destruct BR as [(EH & spread & SPL & PLL) | (NH & _)].
    2: { exfalso. destruct HT1 as [HTa|HTb].
         - rewrite (swrap32_small hT) in KH by lia. Z.div_mod_to_equations. lia.
         - subst hT. rewrite (swrap32_eqm (2^32 - 1) (-1)) in KH by first [lia | vm_compute; reflexivity | vm_compute; split; congruence].
           Z.div_mod_to_equations. lia. }
    eapply bdt_evt_R.
    { eapply (bdt_fpath ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m SPV DT NC WK msv tl fm hT lo nc (skipn 4 jdt) syms1 snext)
        with (jw' := skipn (2 * length snext) jw).
      all: try bprem.
      lazymatch goal with |- forall _, _ => idtac end.
      intros mq q1 q5 q6 q7 q8 q9 q10 q11 q12 q13 q18 q19 q20 q21 q22 q23 q24 q25 q26 q27 q28 q29 q30 q31 QLS QU1 QU2 QU3 QRW QSK QMU QWM QMI.
      eapply bdt_evt_R;
      [ eapply (bdt_tail ra (Z_to_bv 64 SPV) gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m DT WK msv tl fm lo) with (jt := skipn 4 jdt);
        rewrite ?USP; try unfold FSE_DTABLE_SIZE, FSE_BUILD_DTABLE_WKSP_SIZE, FSE_BUILD_STACK; bprem
      | rewrite ?USP; regeq ]. }
    regeq.
  Unshelve.
  all: first [exact (Z_to_bv 64 0) | assumption
    | (rewrite length_skipn; apply Nat2Z.inj; rewrite Nat2Z.inj_sub by lia; rewrite Nat2Z.inj_mul, Z2Nat.id by lia; lia)
    | (repeat split; lia)].
Qed.
